rule CobaltStrike_Shellcode {
    meta:
        description = "Detects encoded Cobalt Strike shellcode in memory or file"
        author = "SOC Team"
        malware_family = "CobaltStrike"
    strings:
        $a = { 60 00 00 00 48 89 E2 48 89 E7 48 83 EC 20 E8 } 
        $b = { 41 51 41 50 52 51 56 48 89 CD 4C 89 C6 } 
    condition:
        all of them
}

